 * Computes the changes needed to turn `base` into `side` using a longest
 * common subsequence over whole lines (exact string comparison). Among LCSs
 * of maximal length, the one whose matches occur earliest is chosen: walking
 * both documents from the start, a match is taken whenever the current lines
 * are equal, and otherwise the side whose remaining subsequence is at least
 * as long as the other's is advanced, with base preferred on a tie.
 *
 * Returns changes ordered by their position in `base`, each describing a run
 * of base lines (`baseStart`..`baseEnd`) replaced by a run of `side` lines
 * (`sideStart`..`sideEnd`). An insertion has `baseStart === baseEnd` and a
 * deletion has `sideStart === sideEnd`. `origin` tags which side produced the
 * change so later stages can tell mine's changes from theirs's.
 */
export function diffChanges(base, side, origin) {
  const m = base.length
  const n = side.length

  // dp[i][j] holds the LCS length of base[i:] and side[j:].
  const dp = new Array(m + 1)
  for (let i = 0; i <= m; i++) dp[i] = new Int32Array(n + 1)
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      dp[i][j] = base[i] === side[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const changes = []
  let i = 0
  let j = 0
  let pendingBaseStart = 0
  let pendingSideStart = 0

  while (i < m && j < n) {
    if (base[i] === side[j]) {
      if (i > pendingBaseStart || j > pendingSideStart) {
        changes.push({ origin, baseStart: pendingBaseStart, baseEnd: i, sideStart: pendingSideStart, sideEnd: j })
      }
      i++
      j++
      pendingBaseStart = i
      pendingSideStart = j
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }

  if (pendingBaseStart < m || pendingSideStart < n) {
    changes.push({ origin, baseStart: pendingBaseStart, baseEnd: m, sideStart: pendingSideStart, sideEnd: n })
  }

  return changes
}
"}

