 * Merges mine's and theirs's changes into a single list ordered by base
 * position (mine before theirs on a tie at the same base start), then walks
 * it: the first remaining change starts a region spanning its base range,
 * and any following change that starts at or before the region's current
 * base end is absorbed, extending the end to cover it.
 */
export function buildRegions(mineChanges, theirsChanges) {
  const all = [...mineChanges, ...theirsChanges].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.origin === b.origin) return 0
    return a.origin === 'mine' ? -1 : 1
  })

  const regions = []
  let index = 0
  while (index < all.length) {
    const group = [all[index]]
    let baseStart = all[index].baseStart
    let baseEnd = all[index].baseEnd
    index++
    while (index < all.length && all[index].baseStart <= baseEnd) {
      baseEnd = Math.max(baseEnd, all[index].baseEnd)
      group.push(all[index])
      index++
    }
    regions.push({ baseStart, baseEnd, changes: group })
  }
  return regions
