  const touching = region.changes.filter(change => change.origin === origin)
  if (touching.length === 0) return base.slice(region.baseStart, region.baseEnd)

  const first = touching[0]
  const last = touching[touching.length - 1]
  const start = first.sideStart - (first.baseStart - region.baseStart)
  const end = last.sideEnd + (region.baseEnd - last.baseEnd)
  return side.slice(start, end)
}

/**
 * Resolves a region to mine's lines, theirs's lines, or a conflict, per the
 * rule: equal sides resolve to mine, otherwise a side that still matches the
 * base loses to the other, otherwise it's a conflict.
 */
export function resolveRegion(base, mine, theirs, region) {
  const mineLines = sideLines(base, mine, region, 'mine')
  const theirsLines = sideLines(base, theirs, region, 'theirs')
  const baseLines = base.slice(region.baseStart, region.baseEnd)
  const hasMine = region.changes.some(change => change.origin === 'mine')
  const hasTheirs = region.changes.some(change => change.origin === 'theirs')

  if (linesEqual(mineLines, theirsLines)) {
    const kind = hasMine && hasTheirs ? 'both' : hasMine ? 'mine' : 'theirs'
    return { kind, lines: mineLines }
  }
