{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-WgeVqx/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */
import { readFileSync } from 'node:fs'
import { diffChanges } from './diff.js'
import { buildRegions, resolveRegion } from './regions.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function splitLines(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function splitDocs(lines) {
  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }
  return parts
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.includes(args[0])) fail('usage: cli.js merge|merge2|regions')
  const mode = args[0]

  const input = readFileSync(0, 'utf8')
  const parts = splitDocs(splitLines(input))
  if (parts.length !== 3) fail('expected three parts separated by %%%')
  const [mine, base, theirs] = parts

  const mineChanges = diffChanges(base, mine, 'mine')
  const theirsChanges = diffChanges(base, theirs, 'theirs')
  const regions = buildRegions(mineChanges, theirsChanges)

  const output = []
  let conflict = false
  let cursor = 0

  for (const region of regions) {
    if (cursor < region.baseStart) emitStable(output, mode, base, cursor, region.baseStart)

    const resolved = resolveRegion(base, mine, theirs, region)
    if (resolved.kind === 'conflict') conflict = true
    emitRegion(output, mode, resolved)

    cursor = region.baseEnd
  }
  if (cursor < base.length) emitStable(output, mode, base, cursor, base.length)

  process.stdout.write(output.join(''))
  process.exit(conflict ? 1 : 0)
}

function emitStable(output, mode, base, start, end) {
  if (mode === 'regions') {
    if (end > start) output.push(`stable ${end - start}\n`)
    return
  }
  for (let i = start; i < end; i++) output.push(`${base[i]}\n`)
}

function emitRegion(output, mode, resolved) {
  if (mode === 'regions') {
    output.push(
      resolved.kind === 'conflict'
        ? `conflict mine=${resolved.mine.length} base=${resolved.base.length} theirs=${resolved.theirs.length}\n`
        : `${resolved.kind} ${resolved.lines.length}\n`,
    )
    return
  }
  if (resolved.kind !== 'conflict') {
    for (const line of resolved.lines) output.push(`${line}\n`)
